import * as T from 'three';
export function createManeuverNode(preview,time){if(Math.abs(preview.deltaV)<.5)throw Error('固定するΔvは0.5 m/s以上にしてください');return {time:time+preview.time,position:preview.burnPos.toArray(),velocity:preview.afterVel.toArray(),impulse:preview.impulse.toArray(),remaining:preview.impulse.toArray(),complete:false};}
export function maneuverDirection(node){return node?new T.Vector3(...(node.complete?node.impulse:node.remaining)).normalize():null;}
export function advanceManeuver(node,engineDeltaV){if(!node)return;const before=new T.Vector3(...node.remaining),fraction=engineDeltaV.lengthSq()?Math.max(0,Math.min(1,before.dot(engineDeltaV)/engineDeltaV.lengthSq())):0,closest=before.clone().addScaledVector(engineDeltaV,-fraction),remaining=before.sub(engineDeltaV);node.remaining=remaining.toArray();node.complete=node.complete||closest.length()<.5;}
export function validateManeuverNode(value){if(value==null)return null;const validArray=(a,limit)=>Array.isArray(a)&&a.length===3&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<=limit);if(!Number.isFinite(value.time)||value.time<0||value.time>1e12||typeof value.complete!=='boolean'||!validArray(value.position,1e10)||!validArray(value.velocity,1e6)||!validArray(value.impulse,10000)||!validArray(value.remaining,1e6)||(new T.Vector3(...value.impulse).length()<.5||new T.Vector3(...value.impulse).length()>10000.001)||(!value.complete&&new T.Vector3(...value.remaining).length()<.5))throw Error('マニューバ計画の保存値が不正です');return structuredClone(value);}
